const now = new Date();
const currentHour = now.getHours() === 0 ? 24 : now.getHours();
const dayNames = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const currentDay = dayNames[now.getDay()];
const staticData = $getWorkflowStaticData('global');
if (!staticData.schedules) return [{ json: { matches: [], hour: currentHour, day: currentDay } }];
const matches = Object.values(staticData.schedules).filter(s => {
  if (!s.active) return false;
  const hourMatch = parseInt(s.hour, 10) === currentHour;
  const dayMatch = (s.days || []).includes(currentDay);
  return hourMatch && dayMatch;
});
return [{ json: { matches, hour: currentHour, day: currentDay, currentDate: now.toISOString() } }];

const data = $input.first().json;
const dateStr = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
const enhancedPrompt = data.prompt + `\n\n=== ÖNEMLİ: BU BİR SCHEDULED ÇALIŞTIRMA ===\nTarih: ${dateStr}\nBu trend önerileri bugünün güncel trendlerini yansıtmalı. Her öneride 'güncellik' vurgusu yap. (örn: 'Bu hafta patlayan format', 'Son 24 saatte viral olan', vs.)\n===`;
const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 8000,
  messages: [{ role: 'user', content: enhancedPrompt }]
};
return [{ json: { ...data, apiBody } }];

const apiData = $input.first().json;
let text = apiData.choices?.[0]?.message?.content || '';
const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);
let result = {};
try { result = JSON.parse(text); } catch(e) { result = { videos: [] }; }
const data = $('Split Out (Loop)').first().json;
const videos = result.videos || [];
const dateStr = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
const sectorText = (data.sector === 'ALL' || !data.sector) ? 'Tüm Sektörler' : data.sector;
const tonesText = (data.tones || []).join(' + ');
const bizText = data.biz || 'İşletmeniz';
let emailContent = `Merhaba! ${bizText} için ${dateStr} tarihli trend video fikirleri:\n\n`;
videos.forEach(v => {
  emailContent += `#${v.rank} — ${v.title}\n`;
  emailContent += `Platform: ${v.platform} | Trend: ${v.trendScore || 'N/A'}\n`;
  emailContent += `Etiketler: ${(v.tags || []).join(', ')}\n`;
  emailContent += `Neden trend: ${v.whyTrending || ''}\n`;
  emailContent += `Markanıza uyarlama: ${v.adaptation || ''}\n\n---\n\n`;
});
const htmlBody = `<!DOCTYPE html><html lang="tr"><head><meta charset="UTF-8"></head><body style="font-family:system-ui,sans-serif;background:#F7F6F2;padding:2rem"><div style="max-width:680px;margin:0 auto;background:#fff;border-radius:16px;padding:2rem;border:0.5px solid #E2E0D8"><div style="color:#1D9E75;font-size:13px;font-weight:500;letter-spacing:.04em;margin-bottom:1.5rem">KOLAY KOBI — TREND VIDEO BULTENI</div><h1 style="font-size:22px;color:#1C1B19;margin-bottom:.4rem">Gunun Trend Video Fikirleri</h1><p style="font-size:14px;color:#6B6963;margin-bottom:2rem"><strong>${bizText}</strong> — ${sectorText}<br/>Ton: ${tonesText}<br/>Tarih: ${dateStr}</p>` + videos.map(v => `<div style="border:0.5px solid #E2E0D8;border-radius:12px;padding:1rem;margin-bottom:1rem"><div style="display:flex;align-items:center;gap:10px;margin-bottom:.75rem"><div style="width:32px;height:32px;border-radius:50%;background:#1D9E75;color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600">${v.rank}</div><div style="font-size:15px;font-weight:500;color:#1C1B19">${v.title}</div></div><div style="font-size:12px;color:#6B6963;margin-bottom:.5rem">${v.platform} | Trend: ${v.trendScore || 'N/A'}</div><div style="background:#DCF8C6;border-radius:0 12px 12px 12px;padding:10px 12px;font-size:13px;color:#1C1B19;line-height:1.6;margin-bottom:.5rem">${v.whyTrending || ''}</div><div style="background:#F7F6F2;border-radius:8px;padding:8px 10px;font-size:12px;color:#6B6963"><strong style="color:#1D9E75">Markaniza uyarlama:</strong> ${v.adaptation || ''}</div>${(v.tags && v.tags.length) ? `<div style="margin-top:.5rem">${v.tags.map(t => `<span style="font-size:11px;padding:2px 8px;background:#F0FAF6;border:0.5px solid #9FE1CB;border-radius:6px;color:#085041;margin-right:4px">${t}</span>`).join('')}</div>` : ''}</div>`).join('') + `<div style="background:#F0FAF6;border-radius:8px;padding:1rem;margin-top:1.5rem;text-align:center"><p style="font-size:13px;color:#0F6E56;margin:0">Bu rapor Kolay KOBİ Trend Video Bulucu tarafindan otomatik olusturuldu.</p><a href="https://kolaykobi.com" style="display:inline-block;background:#1D9E75;color:#fff;padding:10px 24px;border-radius:8px;text-decoration:none;font-size:14px;margin-top:.75rem">Kolay KOBİ'yi Ac</a></div></div></body></html>`;
return [{ json: { ...data, emailContent, htmlBody, videos } }];
